corporate_design.toad_component_blueprint:
canvas {
  size: 920px 600px;
  fill: #F5F2EB;
  font-family: "Plus Jakarta Sans, sans-serif";
}

>chalk = #F5F2EB;
>pineGreen = #2E3D30;
>larchWood = #C7A77B;
>slate = #4A4D48;

rect #drawingCard {
  at: center of canvas;
  size: 820px 500px;
  fill: #FFFFFF;
  stroke: #E2DDD5;
  stroke-width: 1px;
  radius: 8px;
}

text #archHeader {
  at: top left of #drawingCard offset 40px 36px;
  content: "NORDHOLZ ARCHITEKTUR // PROJEKT HAUS EIKEN";
  font-size: 13px;
  font-weight: 600;
  color: >larchWood;
}

text #projectTitle {
  at: below #archHeader offset 12px;
  content: "Passivhaus in Massivholzbauweise";
  font-size: 32px;
  font-weight: 600;
  color: >pineGreen;
}

text #projectMeta {
  at: below #projectTitle offset 14px;
  size: 700px;
  content: "Wohnfläche: 184 m² • Standort: Schleswig-Holstein • KfW 40 Plus Standard mit sichtbaren Brettsperrholzdecken und Erdwärmepumpe.";
  font-size: 14px;
  color: >slate;
}
